def transform(grid):
    out = [row[:] for row in grid]
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    markers = {v for row in grid for v in row if v != background}
    # The template is the only horizontal run of five non-background cells.
    template = None
    for row in grid:
        for c in range(len(row) - 4):
            run = row[c:c+5]
            if all(v != background for v in run):
                template = run
                break
        if template is not None:
            break
    marker = next(v for v in markers if v not in template)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == marker:
                for j, color in enumerate(template):
                    if 0 <= c - 2 + j < len(row):
                        out[r][c - 2 + j] = color
    return out
